  /* 바탕 화면(lsm) 안에 이 팝업을 얹은 마크업 — 미리보기와 스튜디오가 같이 쓴다.
     문자열을 자르지 않고 DOM 으로 심는다(바탕 마크업의 닫는 자리를 추측하지 않으려고). */
  window.build_lsm_cooling = function (base) {
    var d = document.createElement('div');
    d.innerHTML = window.build_lsm(base);
    var frame = d.querySelector('[data-name^="Screen/"]') || d.firstElementChild;
    var m = document.createElement('div');
    m.className = 'lsc-mount ls-popmount';
    m.setAttribute('data-name', "Popup/Cooling System - Status");
    m.innerHTML = '<div class="lsc-root ls-pop">' + window.build_lsc(base) + '</div>';
    frame.appendChild(m);
    return d.innerHTML;
  };
